import fitz
doc = fitz.open('/app/paper.pdf')
for i, page in enumerate(doc):
    text = page.get_text()
    if 'r2' in text.lower() or 'r²' in text.lower() or 'bin' in text.lower():
        # Look for specific R2 values or binning info
        lines = text.split('\n')
        for j, line in enumerate(lines):
            ll = line.lower()
            if 'r2' in ll or 'r²' in ll or 'bin' in ll or 'bin size' in ll:
                print(f'Page {i+1}, line {j}: {line.strip()}')
" 2>&1 | head -40

